#!/bin/bash
# usage: run_one.sh <key> "<design brief>"   (Codex headless repaint of cell 0 of a Frost enemy; output src/<key>_new.png)
D="$(cd "$(dirname "$0")" && pwd)"; N="$1"; BRIEF="$2"
PROMPT="You are redesigning ONE game enemy sprite (attached image: ${N}_in.png, transparent background, top-down view, same camera). Use your image generation tool to produce a NEW image of the SAME enemy concept: same pose, camera, overall silhouette and part layout, same pixel-art style (crisp hard pixel edges, dense 4-6 tone ramps, rivets, scratches), on a genuinely transparent square background, generous margin, sprite centred and filling about the same area. Do a ground-up repaint with a sensible, readable palette segmented by REAL part boundaries (never gradients or bands by position): ${BRIEF} Structure: one coherent mid-bright hull family, a darker second plate material, metal trim (brass/bronze/steel) on structural parts, a bright glowing core, flame or jet at engines/thrusters. The look must stay cold and Frost-world but be readable against a dark indigo backdrop. NO outline of any kind: no pale rim, no white border, no glow halo, no dark outline ring; edges are just the painted body against transparency. FORBIDDEN: pink, magenta, red, text, shadow, background. Output exactly one sprite. Save the final RGBA PNG to ${D}/src/${N}_new.png (copy it from the generated images folder if needed) and reply with just the path."
printf "%s" "$PROMPT" | ~/.local/bin/codex exec -m gpt-5.6-luna --skip-git-repo-check -s workspace-write -C "$D/src" -i "$D/src/${N}_in.png" -
